html`&lt;div style="display:flex; gap:1.2rem; flex-wrap:wrap; align-items:center; justify-content:center;"&gt;${singleDiagram}${singlePlot}&lt;/div&gt;`




























































Step 2 — Two Neurons Make a Bump
Take two step neurons with step points s_1 &lt; s_2, and feed both into the next neuron with opposite-signed weights +h and -h: \text{output} \approx h\cdot\mathbf{1}[x \ge s_1] - h\cdot\mathbf{1}[x \ge s_2]
= h\cdot\mathbf{1}[s_1 \le x &lt; s_2]. The two steps cancel everywhere except the interval [s_1, s_2), leaving a single rectangular bump of height h, the basic unit we’ll tile the domain with next.

Step 2 — Two Neurons → One Bump

viewof twoBumpS1 = Inputs.range([0, 1], { value: 0.2, step: 0.01, label: "step point s₁" })
viewof twoBumpS2 = Inputs.range([0, 1], { value: 0.6, step: 0.01, label: "step point s₂" })
viewof twoBumpH  = Inputs.range([-2, 2], { value: 1.2, step: 0.05, label: "height h" })

twoBumpLo = Math.min(twoBumpS1, twoBumpS2)
twoBumpHi = Math.max(twoBumpS1, twoBumpS2)
twoBumpC  = 250 // steepness constant; large w approximates a hard step

twoBumpStep = (x, s) =&gt; 1 / (1 + Math.exp(-twoBumpC * (x - s)))
twoBumpFn   = x =&gt; twoBumpH * (twoBumpStep(x, twoBumpLo) - twoBumpStep(x, twoBumpHi))

twoBumpXs = Array.from({ length: 500 }, (_, i) =&gt; -0.1 + i * (1.2 / 499))

twoBumpPlot = Plot.plot({
  width: 380, height: 230,
  marginLeft: 42,
  x: { label: "x →", domain: [-0.1, 1.1], grid: true },
  y: { label: "output", domain: [-2.2, 2.2], grid: true },
  marks: [
    Plot.ruleY([0], { stroke: "#eee" }),
    Plot.line(twoBumpXs.map(x =&gt; ({ x, y: twoBumpH * twoBumpStep(x, twoBumpLo) })),
      { x: "x", y: "y", stroke: "#9fa8da", strokeWidth: 1.5, strokeDasharray: "5,3" }),
    Plot.line(twoBumpXs.map(x =&gt; ({ x, y: -twoBumpH * twoBumpStep(x, twoBumpHi) })),
      { x: "x", y: "y", stroke: "#c5cae9", strokeWidth: 1.5, strokeDasharray: "5,3" }),
    Plot.line(twoBumpXs.map(x =&gt; ({ x, y: twoBumpFn(x) })),
      { x: "x", y: "y", stroke: "#5c6bc0", strokeWidth: 2.5 })
  ]
})

